    private void tNilaiAkhirKeyPressed(java.awt.event.KeyEvent evt) {//GEN-FIRST:event_tNilaiAkhirKeyPressed
        // TODO add your handling code here:
        if (evt.getKeyCode()==KeyEvent.VK_ENTER) {
            String ket;
            int a = Integer.parseInt(tNilaiAkhir.getText());
            if (a>=70){
                ket = "Lulus";
            }else{
                ket = "Tidak Lulus";
            }
            String b = ket;
            
            tPenentuan.setText((b));
            
        }
    }//GEN-LAST:event_tNilaiAkhirKeyPressed

