    private void bRepeatActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_bRepeatActionPerformed
        // TODO add your handling code here:
        tNilaiAkhir.setText("");
        tPenentuan.setText("");
        tNilaiAkhir.setEnabled(true);
        tPenentuan.setEnabled(true);
        tNilaiAkhir.requestFocus();
    }//GEN-LAST:event_bRepeatActionPerformed

